"use client";
import * as React from "react";
import { useReferenceRef } from "@/lib/cojeev/reference-ref";
import { cn } from "@/lib/utils";
import { bounded } from "@/lib/cojeev/reference-text-math";
import { useReferenceText,type ReferenceTextSize } from "@/lib/cojeev/reference-text-motion";
export type ParticleTextProps=Omit<React.ComponentProps<"div">,"children">&{text:string;density?:number;particleSize?:number;repelRadius?:number;paused?:boolean;replayKey?:number|string;size?:ReferenceTextSize};
/** Samples the actual font's alpha mask, then gathers those samples into text. */
export function ParticleText({text,density=5,particleSize=1.5,repelRadius=70,paused=false,replayKey=0,size="default",className,ref,onPointerMove,onPointerLeave,...props}:ParticleTextProps){
 const {host:hostRef,running}=useReferenceText(paused),canvas=React.useRef<HTMLCanvasElement>(null),pointer=React.useRef<{x:number;y:number}|null>(null);
 React.useEffect(()=>{
  const el=hostRef.current,surface=canvas.current;if(!el||!surface||!running)return;
  const ctx=surface.getContext("2d");if(!ctx)return;
  let disposed=false,frame=0,start=0,w=1,h=1,ink="",particles:{x:number;y:number;tx:number;ty:number;seed:number}[]=[];
  const build=()=>{
   if(disposed)return;const r=el.getBoundingClientRect();w=Math.round(Math.min(900,Math.max(1,r.width)));h=Math.round(Math.min(420,Math.max(1,r.height)));surface.width=w;surface.height=h;
   const style=getComputedStyle(el);ink=style.color;
   const sample=document.createElement("canvas");sample.width=w;sample.height=h;const mask=sample.getContext("2d",{willReadFrequently:true});if(!mask)return;
   let font=bounded(parseFloat(style.fontSize)*1.3,20,100,64);mask.font=`650 ${font}px ${style.fontFamily}`;
   const words=text.trim().split(/\s+/),lines:string[]=[];let line="";
   for(const word of words){const next=line?line+" "+word:word;if(line&&mask.measureText(next).width>w*.85){lines.push(line);line=word;}else line=next;}if(line)lines.push(line);
   const maxWidth=Math.max(1,...lines.map(x=>mask.measureText(x).width));font*=Math.min(1,w*.85/maxWidth,h*.7/Math.max(font,lines.length*font*1.2));
   mask.font=`650 ${font}px ${style.fontFamily}`;mask.fillStyle="#000";mask.textAlign="center";mask.textBaseline="middle";
   lines.forEach((l,i)=>mask.fillText(l,w/2,h/2+(i-(lines.length-1)/2)*font*1.2));
   const alpha=mask.getImageData(0,0,w,h).data,step=Math.max(bounded(density,3,10,5),Math.sqrt(w*h/4000));particles=[];
   for(let y=0;y<h;y+=step)for(let x=0;x<w;x+=step){if(alpha[(Math.floor(y)*sample.width+Math.floor(x))*4+3]>100){const seed=((x*13+y*7)%101)/101;particles.push({tx:x,ty:y,x:w/2+Math.cos(seed*16)*w*.6,y:h/2+Math.sin(seed*19)*h*.7,seed});}}
   el.dataset.ready=String(particles.length>0);start=0;
  };
  const draw=(now:number)=>{
   if(disposed)return;if(!start)start=now;ctx.clearRect(0,0,w,h);ctx.fillStyle=ink;
   const p=bounded((now-start)/1800,0,1,1),gather=1-Math.pow(1-p,3),radius=bounded(repelRadius,10,200,70);
   for(const dot of particles){let x=dot.tx+(dot.x-dot.tx)*(1-gather),y=dot.ty+(dot.y-dot.ty)*(1-gather);
    if(pointer.current){const dx=x-pointer.current.x,dy=y-pointer.current.y,d=Math.hypot(dx,dy);if(d<radius&&d>0){const force=(1-d/radius)**2*34;x+=dx/d*force;y+=dy/d*force;}}
    ctx.beginPath();ctx.arc(x,y,bounded(particleSize,.7,4,1.5),0,Math.PI*2);ctx.fill();
   }frame=requestAnimationFrame(draw);
  };
  const observer=new ResizeObserver(build);observer.observe(el);const appearance=new MutationObserver(build);for(let parent:HTMLElement|null=el;parent;parent=parent.parentElement)appearance.observe(parent,{attributes:true,attributeFilter:["data-mode","class"]});window.addEventListener("cojeev:appearancechange",build);build();void document.fonts.ready.then(()=>{if(!disposed)build();});frame=requestAnimationFrame(draw);
  return()=>{disposed=true;cancelAnimationFrame(frame);observer.disconnect();appearance.disconnect();window.removeEventListener("cojeev:appearancechange",build);el.dataset.ready="false";pointer.current=null;};
 },[hostRef,running,text,density,particleSize,repelRadius,replayKey]);
 return <div {...props} ref={useReferenceRef(hostRef,ref)} data-slot="particle-text" data-size={size} data-running={running} className={cn("v-particle-text",className)}
 onPointerMove={event=>{onPointerMove?.(event);if(!running||event.defaultPrevented||event.pointerType==="touch")return;const r=event.currentTarget.getBoundingClientRect();pointer.current={x:(event.clientX-r.left)*Math.min(900,r.width)/r.width,y:(event.clientY-r.top)*Math.min(420,r.height)/r.height};}}
 onPointerLeave={event=>{onPointerLeave?.(event);pointer.current=null;}}>
 <span className="v-particle-text__words">{text}</span><canvas ref={canvas} aria-hidden="true"/>
 </div>;
}

"use client";
import * as React from "react";
import { assignMotionRef } from "@/lib/cojeev-motion/refs";

/** Preserve caller refs while the effect observes the same DOM element. */
export function useReferenceRef<T>(hostRef: React.RefObject<T | null>, forwardedRef: React.Ref<T> | undefined) {
  return React.useCallback((node: T | null) => {
    hostRef.current = node;
    const cleanup = assignMotionRef(forwardedRef, node);
    return () => { hostRef.current = null; cleanup(); };
  }, [hostRef, forwardedRef]);
}

import type * as React from 'react'
/** React 19 callback refs may return their own teardown; object refs are mutable commit targets. */
export function assignMotionRef<T>(ref:React.Ref<T>|undefined,value:T|null):()=>void{
 if(typeof ref==='function'){
  const cleanup=ref(value)
  return ()=>{if(typeof cleanup==='function')cleanup();else ref(null)}
 }
 if(ref)ref.current=value
 return ()=>{if(ref)ref.current=null}
}

export const bounded = (value: number, min: number, max: number, fallback: number) => Number.isFinite(value) ? Math.max(min, Math.min(max, value)) : fallback;
export const graphemes = (text: string) => Array.from(new Intl.Segmenter(undefined, { granularity: "grapheme" }).segment(text), item => item.segment);
export function proximityWeight(distance: number, radius: number, from: number, to: number) {
  const p = 1 - bounded(distance / bounded(radius, 1, 1000, 120), 0, 1, 1);
  return from + (to - from) * p * p * (3 - 2 * p);
}
export function scrollWordProgress(progress: number, index: number, count: number) {
  return bounded(progress * (Math.max(1, count) + 2) - index, 0, 1, 1);
}
export function caretFrame(from: string, to: string, progress: number) {
  const p = bounded(progress, 0, 1, 1), chars = graphemes(to);
  if (p < .25) return { text: from, phase: "holding", cover: 0 };
  if (p < .42) return { text: from, phase: "covering", cover: (p - .25) / .17 };
  if (p < .55) return { text: "", phase: "collapsing", cover: 1 - (p - .42) / .13 };
  return { text: chars.slice(0, Math.ceil(chars.length * Math.pow((p - .55) / .45, .7))).join(""), phase: p === 1 ? "complete" : "typing", cover: 0 };
}
export type FallingBody = { x: number; y: number; vx: number; vy: number; w: number; h: number; angle: number };
export function fallStep(body: FallingBody, width: number, height: number, delta: number, gravity: number): FallingBody {
  const dt = bounded(delta, 0, 32, 16) / 1000;
  let vx = body.vx, vy = body.vy + bounded(gravity, 0, 2400, 900) * dt;
  let x = body.x + vx * dt, y = body.y + vy * dt;
  const right = Math.max(0, width - body.w), floor = Math.max(0, height - body.h);
  if (x < 0 || x > right) { x = bounded(x, 0, right, 0); vx *= -.55; }
  if (y > floor) { y = floor; vy = Math.abs(vy) < 35 ? 0 : -vy * .36; vx *= .85; }
  y = Math.max(0, y);
  return {...body, x, y, vx, vy, angle: bounded(body.angle + vx * dt * .015, -12, 12, 0)};
}

"use client";
import * as React from "react";
import { useMotionVisibility } from "@/lib/cojeev-motion/use-motion-visibility";
export function useReferenceText(paused = false) {
  const host = React.useRef<HTMLDivElement>(null);
  const { enabled, inView } = useMotionVisibility(host);
  return { host, enabled, inView, running: enabled && inView && !paused };
}
/** A single bounded clock. Interruption freezes elapsed time; cleanup cancels its frame. */
export function useReferenceClock(running: boolean, draw: (elapsed: number, delta: number) => boolean | void, replayKey: string | number = 0) {
  const elapsed = React.useRef(0), callback = React.useRef(draw);
  React.useLayoutEffect(() => { callback.current = draw; });
  React.useEffect(() => { elapsed.current = 0; }, [replayKey]);
  React.useEffect(() => {
    if (!running) return;
    let frame = 0, previous = 0;
    const tick = (now: number) => {
      const delta = previous ? Math.min(32, now - previous) : 0;
      previous = now; elapsed.current += delta;
      if (callback.current(elapsed.current, delta) !== false) frame = requestAnimationFrame(tick);
    };
    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [running, replayKey]);
}
export type ReferenceTextSize = "sm" | "default" | "lg";
export type ReferenceTextTone = "ink" | "pink" | "olive" | "blue" | "yellow";

"use client";
import * as React from "react";
import { getServerSettingsSnapshot, getSettingsSnapshot, subscribeSettings } from "@/lib/cojeev-motion/settings";

function subscribePreferences(listener: () => void) {
  const media = window.matchMedia("(prefers-reduced-motion: reduce)");
  media.addEventListener("change", listener);
  document.addEventListener("visibilitychange", listener);
  return () => {
    media.removeEventListener("change", listener);
    document.removeEventListener("visibilitychange", listener);
  };
}
function readPreferences() {
  return document.visibilityState === "visible" && !window.matchMedia("(prefers-reduced-motion: reduce)").matches;
}
/** A shared stillness boundary for optional landing-page effects. */
export function useMotionVisibility(ref: React.RefObject<Element | null>, mountedElement?: Element | null) {
  const { motion, flow } = React.useSyncExternalStore(subscribeSettings, getSettingsSnapshot, getServerSettingsSnapshot);
  const permitted = React.useSyncExternalStore(subscribePreferences, readPreferences, () => false);
  const [inView, setInView] = React.useState(false);
  React.useEffect(() => {
    const element = mountedElement ?? ref.current;
    if (!element) { setInView(false); return; }
    const observer = new IntersectionObserver(([entry]) => setInView(entry.isIntersecting), { threshold: 0.1 });
    observer.observe(element);
    return () => observer.disconnect();
  }, [ref, mountedElement]);
  return { enabled: permitted && motion.mode !== "off" && flow.variant !== "off", inView };
}

export const RUNTIME={cfg:{rest:false,reach:true,merge:true,hold:true,jiggleOn:true,press:true,echo:false,dots:0,grain:.08,sheen:.6,curve:1.2,lobeK:130,lobeZ:1,mergeZ:.8,arcK:40,holdK:80,pressK:170,jiggle:.35,jiggleDecay:1.6,restSpeed:1,drift:1,quality:2.5},
 tier:{pill:{amp:0,reach:3,inside:1.2,press:.02},tile:{amp:0,reach:2.4,inside:1,press:.02},nav:{amp:0,reach:1.2,inside:.5,press:.008},card:{amp:0,reach:1,inside:.4,press:.004},blob:{amp:.006,reach:3,inside:1.2,press:.03}}};
/* Per-tier authoring domains live with the profile, so a slider cannot offer a value the tier cannot mean
   (the spinner's amp .14 is legitimate and must not be clamped to the pill's 3 % ceiling). */
export const DOMAIN={amp:{max:{pill:3,tile:3,nav:1,card:1,blob:8,spinner:20},min:0},reach:{max:{pill:24,tile:24,nav:12,card:12,blob:32,spinner:0},min:0},inside:{max:{pill:12,tile:12,nav:6,card:6,blob:16,spinner:0},min:0},press:{max:{pill:12,tile:12,nav:4,card:4,blob:16,spinner:0},min:0},R:{max:{pill:240,tile:240,nav:160,card:160,blob:320,spinner:0},min:0},sig:{max:{pill:120,tile:120,nav:80,card:160,blob:160,spinner:8},min:1}};
export const factoryTiers={pill:{amp:.008,reach:4,inside:2,sig:24,R:80,press:.03,lobes:0,depth:0,asym:0,spread:.55},tile:{amp:.008,reach:3.5,inside:1.6,sig:18,R:64,press:.035,lobes:0,depth:0,asym:0,spread:.55},nav:{amp:.0006,reach:3,inside:1.2,sig:24,R:64,press:.010,lobes:0,depth:0,asym:0,spread:.55},card:{amp:.0003,reach:2.5,inside:.9,sig:44,R:56,press:.004,lobes:0,depth:0,asym:0,spread:.55},blob:{amp:.012,reach:4,inside:1.8,sig:22,R:64,press:.05,lobes:0,depth:0,asym:0,spread:.55},spinner:{amp:.14,reach:0,inside:0,sig:1,R:0,press:0,lobes:0,depth:0,asym:0,spread:.55}};
export const factoryCfg={quality:2.5,grain:.12,sheen:1,curve:1,lobeK:90,lobeZ:.9,mergeZ:.62,arcK:26,holdK:55,pressK:140,jiggle:.45,jiggleDecay:1.35,restSpeed:1,drift:1,rest:true,reach:true,merge:true,hold:true,jiggleOn:true,press:true,echo:false,echoOff:6,echoScale:1.04,dots:0};


export type MorphConfig = typeof factoryCfg
export type TierName = keyof typeof factoryTiers
export type Tier = typeof factoryTiers.pill
export type ProductCategory = "buttons" | "icons" | "pills" | "cards" | "skeleton"
export type Category = ProductCategory | "nav" | "inputs" | "controls" | "surfaces"
export type MotionSettings = {v:3;mode:"off"|"subtle";cats:Record<Category,boolean>}
export type MorphProfile = {cfg:MorphConfig;TIER:Record<TierName,Tier>}
export type FlowVariant = "glide"|"stretch"|"jelly"|"comet"|"drop"|"rubber"|"pebble"|"ripple"|"halo"|"off"
export type FlowSettings = {variant:FlowVariant;hover:boolean;speed:number;intensity:number;hoverStrength:number}
export type SettingsSnapshot = Readonly<{motion:MotionSettings;flow:FlowSettings;profile:MorphProfile;authored:boolean}>
export const MOTION_KEY = "v-motion"
export const MORPH_KEY = "v-morph-cfg-v3"
export const FLOW_KEY = "v-flow-v1"
export const PRODUCT_CATEGORIES:readonly ProductCategory[] = ["buttons","icons","pills","cards","skeleton"]
export const FLOW_DEFAULTS:Readonly<FlowSettings> = Object.freeze({variant:"glide",hover:true,speed:1,intensity:1,hoverStrength:1})
export const FLOW_CHARACTERS:Record<FlowVariant,{label:string;duration:number;ease:string;land:string;glow?:string}> = {
 glide:{label:"Glide",duration:.24,ease:"cubic-bezier(.2,.8,.2,1)",land:"none"},
 stretch:{label:"Stretch",duration:.3,ease:"cubic-bezier(.3,1.15,.4,1)",land:"vf-land"},
 jelly:{label:"Jelly",duration:.5,ease:"cubic-bezier(.3,1.3,.45,1)",land:"vf-jellyx"},
 comet:{label:"Comet",duration:.34,ease:"cubic-bezier(.2,.8,.2,1)",land:"vf-land"},
 drop:{label:"Ink drop",duration:.3,ease:"cubic-bezier(.3,1.25,.4,1)",land:"vf-bloom"},
 rubber:{label:"Rubber",duration:.36,ease:"cubic-bezier(.3,1.3,.4,1)",land:"vf-land"},
 pebble:{label:"Pebble",duration:.46,ease:"cubic-bezier(.32,1.25,.42,1)",land:"vf-lean"},
 ripple:{label:"Ripple",duration:.36,ease:"cubic-bezier(.2,.8,.2,1)",land:"vf-land",glow:"vf-ring"},
 halo:{label:"Halo",duration:.4,ease:"cubic-bezier(.3,1.2,.4,1)",land:"vf-land",glow:"vf-glow"},
 off:{label:"Off",duration:0,ease:"linear",land:"none"},
}
const defaultSettings:MotionSettings={v:3,mode:"subtle",cats:{buttons:true,icons:true,pills:true,cards:false,skeleton:true,nav:false,inputs:false,controls:false,surfaces:false}}
function runtime():MorphProfile {
 const TIER=structuredClone(factoryTiers)
 for(const name of Object.keys(RUNTIME.tier) as (keyof typeof RUNTIME.tier)[]) Object.assign(TIER[name],RUNTIME.tier[name])
 return {cfg:{...factoryCfg,...RUNTIME.cfg},TIER}
}
function immutable<T>(value:T):T {
 if(value && typeof value==="object"){Object.values(value).forEach(immutable);Object.freeze(value)}
 return value
}
const serverSnapshot:SettingsSnapshot=immutable({motion:structuredClone(defaultSettings),flow:{...FLOW_DEFAULTS},profile:runtime(),authored:false})
let settings=structuredClone(defaultSettings), profile=runtime(), flow={...FLOW_DEFAULTS}, authored=false, loaded=false
let snapshot=serverSnapshot
const listeners=new Set<()=>void>()
let releaseEvents:undefined|(()=>void), dispatching=false
function storage(){try{return typeof window==="undefined"?null:window.localStorage}catch{return null}}
function parse(key:string):unknown {try{return JSON.parse(storage()?.getItem(key)||"null")}catch{return null}}
function record(value:unknown):value is Record<string,unknown>{return !!value&&typeof value==="object"&&!Array.isArray(value)}
function mergeProfile(value:unknown,base:MorphProfile,strict=false):MorphProfile {
 if(!record(value)||(!record(value.cfg)&&!record(value.TIER)))throw new Error("Profile must contain a cfg or TIER object.")
 const next=structuredClone(base)
 if(record(value.cfg)) for(const key of Object.keys(next.cfg) as (keyof MorphConfig)[]){
  const v=value.cfg[key];if(v===undefined)continue
  if(typeof v!==typeof next.cfg[key]||(typeof v==="number"&&!Number.isFinite(v))){if(strict)throw new Error(`Invalid cfg.${key}: expected a finite ${typeof next.cfg[key]}.`);continue}
  Object.assign(next.cfg,{[key]:v})
 }
 if(record(value.TIER))for(const name of Object.keys(next.TIER) as TierName[]){const saved=value.TIER[name];if(!record(saved))continue
  for(const key of Object.keys(next.TIER[name]) as (keyof Tier)[]){const v=saved[key];if(v===undefined)continue
   if(typeof v!=="number"||!Number.isFinite(v)){if(strict)throw new Error(`Invalid TIER.${name}.${key}: expected a finite number.`);continue}
   next.TIER[name][key]=v
  }
 }
 return next
}
function normalizeFlow(value:unknown):FlowSettings {
 const v=record(value)?value:{},number=(key:string,fallback:number,min:number)=>typeof v[key]==="number"&&Number.isFinite(v[key])?Math.max(min,v[key] as number):fallback
 return {variant:typeof v.variant==="string"&&Object.hasOwn(FLOW_CHARACTERS,v.variant)?v.variant as FlowVariant:"glide",hover:typeof v.hover==="boolean"?v.hover:true,speed:number("speed",1,.25),intensity:number("intensity",1,0),hoverStrength:number("hoverStrength",1,0)}
}
export function flowToken(name:string,fallback:string,el?:Element){try{return getComputedStyle(el??document.documentElement).getPropertyValue(name).trim()||fallback}catch{return fallback}}
export function flowTokenMs(name:string,fallback:number,el?:Element){const v=flowToken(name,"",el),n=parseFloat(v);return Number.isFinite(n)?n*(v.endsWith("ms")?1:1000):fallback}
export function applyFlowSettings(){
 if(typeof document==="undefined")return
 const h=document.documentElement,variant=settings.mode==="off"?"off":flow.variant,c=FLOW_CHARACTERS[variant]
 h.dataset.flow=variant;h.dataset.flowHover=flow.hover?"on":"off"
 h.style.setProperty("--flow-speed",String(flow.speed));h.style.setProperty("--flow-intensity",String(flow.intensity));h.style.setProperty("--flow-hover",String(flow.hoverStrength))
 h.style.setProperty("--flow-ease",variant==="off"?c.ease:flowToken("--e-flow-"+variant,c.ease))
 h.style.setProperty("--flow-dur",((variant==="off"?0:flowTokenMs("--t-flow-"+variant,c.duration*1000))/1000/flow.speed).toFixed(3)+"s")
